{
  "strategy_id": "agent_practical",
  "strategy_title": "2주 집중: 가상 규정 기반 최소 RAG 시제품 구축",
  "summary": "Python 기반 개발 경험을 활용하여, 2주(주 3시간) 동안 '가상 규정 3건'을 데이터로 활용한 최소 RAG 시제품을 구축하는 로드맵입니다. LLM/RAG 초보자를 위해 벡터 DB 설정, 임베딩, 검색 로직, 그리고 '근거 표시' 및 '답변 불가' 판별 로직 구현에 집중합니다. 유료 서비스 없이 무료 오픈소스 도구와 Microsoft Learn 무료 모듈을 활용하여 시간과 비용(20,000원 이내)을 최적화했습니다.",
  "project_goal": "가상 규정 3건에서 질문 5건의 근거를 표시하고, 근거 없는 질문은 구분하는 최소 RAG 시제품 구현",
  "total_duration_weeks": 2,
  "roadmap_flow": [
    {
      "step": 1,
      "title": "환경 구축 및 데이터 전처리",
      "duration": "3.5 hours",
      "focus": "Python 환경 설정, 가상 규정 3건 텍스트 데이터 구조화, 임베딩 모델 선택 및 벡터 저장소(ChromaDB 등) 초기화"
    },
    {
      "step": 2,
      "title": "RAG 파이프라인 핵심 로직 구현",
      "duration": "4.0 hours",
      "focus": "문서 분할(Chunking), 임베딩 생성, 유사도 검색(Search) 구현, 검색 결과 기반 프롬프트 템플릿 설계"
    },
    {
      "step": 3,
      "title": "근거 표시 및 답변 불가 판별 로직 개발",
      "duration": "3.5 hours",
      "focus": "LLM 응답에 출처(Chunk ID/문단) 포함 로직, 검색 점수 임계값(Cutoff) 기반 '답변 불가' 판별, 질문 5건 테스트 케이스 작성 및 실행"
    },
    {
      "step": 4,
      "title": "시제품 검증 및 개선",
      "duration": "2.0 hours",
      "focus": "테스트 결과 분석(검색 성공/누락/불가 구분 확인), 프롬프트 미세 조정, 최종 시제품 코드 정리 및 학습 노트 작성"
    }
  ],
  "milestones": [
    {
      "phase": 1,
      "phase_name": "기반 구축 및 데이터 준비",
      "duration": "Week 1 (Day 1-2)",
      "focus_goal": "RAG 실행 환경 구축 및 가상 규정 데이터의 벡터화 완료",
      "key_actions": [
        "Python 가상환경 및 필수 라이브러리(langchain, chromadb, openai 등) 설치",
        "가상 규정 3건 텍스트 파일을 JSON/CSV로 구조화",
        "무료 임베딩 모델(예: OpenAI text-embedding-3-small 또는 로컬 모델) 설정",
        "벡터 데이터베이스에 규정 문서 임베딩 저장"
      ],
      "deliverables": [
        "실행 가능한 Python 환경",
        "벡터화된 가상 규정 데이터셋"
      ],
      "recommended_courses": [
        {
          "course_id": "MS_df219eb945ff"
        }
      ],
      "recommended_books": [],
      "recommended_certifications": []
    },
    {
      "phase": 2,
      "phase_name": "RAG 코어 로직 구현",
      "duration": "Week 1 (Day 3-4) & Week 2 (Day 1)",
      "focus_goal": "질문 입력 시 관련 규정 문단을 검색하고 LLM에 전달하는 파이프라인 완성",
      "key_actions": [
        "문서 분할 전략(문단/문장 단위) 적용 및 Chunking 구현",
        "유사도 검색(Search) 함수 구현 및 Top-K 파라미터 튜닝",
        "검색 결과를 컨텍스트로 포함하는 프롬프트 템플릿 작성",
        "LLM API 호출 및 응답 생성 로직 연결"
      ],
      "deliverables": [
        "기본 RAG 파이프라인 코드",
        "검색-생성 연결 테스트 결과"
      ],
      "recommended_courses": [
        {
          "course_id": "MS_df219eb945ff"
        }
      ],
      "recommended_books": [],
      "recommended_certifications": []
    },
    {
      "phase": 3,
      "phase_name": "근거 표시 및 예외 처리 로직",
      "duration": "Week 2 (Day 2-3)",
      "focus_goal": "답변에 근거를 명시하고, 근거가 없는 질문을 정확히 구분하는 로직 구현",
      "key_actions": [
        "검색된 Chunk의 메타데이터(출처, 위치)를 응답에 포함하는 로직 개발",
        "유사도 점수 임계값 설정 및 '근거 없음' 판별 조건 구현",
        "질문 5건(근거 있음 3건, 근거 없음 2건) 테스트 케이스 작성",
        "테스트 실행 및 출력 결과 검증"
      ],
      "deliverables": [
        "근거 표시 및 답변 불가 판별 기능 구현 코드",
        "테스트 케이스 5건 실행 결과 로그"
      ],
      "recommended_courses": [
        {
          "course_id": "MS_d1f2eed6c592"
        }
      ],
      "recommended_books": [],
      "recommended_certifications": []
    },
    {
      "phase": 4,
      "phase_name": "최종 검증 및 마무리",
      "duration": "Week 2 (Day 4-5)",
      "focus_goal": "시제품 안정성 확인 및 학습 내용 정리",
      "key_actions": [
        "테스트 결과 분석 및 프롬프트/임계값 미세 조정",
        "코드 리팩토링 및 주석 추가",
        "학습 과정 및 문제 해결 방법 정리(학습 노트)",
        "시제품 실행 스크립트 최종 확인"
      ],
      "deliverables": [
        "최종 RAG 시제품 코드",
        "학습 노트 및 테스트 결과 보고서"
      ],
      "recommended_courses": [
        {
          "course_id": "MS_41fd82f2348f"
        }
      ],
      "recommended_books": [],
      "recommended_certifications": []
    }
  ],
  "regulation_citations": [],
  "clarification_questions": []
}
